# Supply-chain dependency graph + CVE reachability map.
#
# From a CycloneDX JSON SBOM (generated by trivy) we render a dependency graph
# and identify each component's known CVEs (from osv-scanner results). This is
# the "which vulnerable packages am I actually pulling in / reachable?" view —
# the cutting-edge supply-chain picture on top of SCA.
import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger("h4k.sbom")

REACHABLE_REL_BOM = "https://cyclonedx.org/schema/bom-1.4.schema.json"


def parse_sbom(sbom_path_or_data: str | Path) -> list[dict[str, Any]]:
    """Parse a CycloneDX JSON doc -> list of component dicts.

    Returns [{bom-ref, type, name, version, purl, licenses}] or [] on error.
    """
    if isinstance(sbom_path_or_data, (str, Path)) and Path(sbom_path_or_data).exists():
        data = json.loads(Path(sbom_path_or_data).read_text(encoding="utf-8"))
    elif isinstance(sbom_path_or_data, str):
        try:
            data = json.loads(sbom_path_or_data)
        except json.JSONDecodeError:
            return []
    else:
        data = sbom_path_or_data

    comps: list[dict[str, Any]] = []
    for c in (data or {}).get("components", []) or []:
        licenses = []
        for lic in c.get("licenses", []) or []:
            lic_obj = lic.get("license", {}) or {}
            name = lic_obj.get("name") or lic_obj.get("id")
            if name:
                licenses.append(name)
        comps.append(
            {
                "bom_ref": c.get("bom-ref") or str(c.get("name", "")),
                "type": c.get("type", ""),
                "name": c.get("name", ""),
                "version": c.get("version", ""),
                "purl": c.get("purl", ""),
                "licenses": licenses,
            }
        )
    return comps


def build_graph(sbom_path_or_data: str | Path) -> dict[str, Any]:
    """Return {nodes, edges} adjacency from the SBOM's dependencies section."""
    if isinstance(sbom_path_or_data, (str, Path)) and Path(sbom_path_or_data).exists():
        data = json.loads(Path(sbom_path_or_data).read_text(encoding="utf-8"))
    else:
        data = (
            json.loads(sbom_path_or_data)
            if isinstance(sbom_path_or_data, str)
            else sbom_path_or_data
        )

    # Components indexed by bom-ref (kept in case callers want a lookup).
    comps = parse_sbom(data)

    nodes = [
        {
            "id": c["bom_ref"],
            "label": f"{c['name']}@{c['version']}",
            "type": c["type"],
            "purl": c["purl"],
        }
        for c in comps
    ]

    edges: list[dict[str, str]] = []
    seen: set[str] = set()
    for dep in (data or {}).get("dependencies", []) or []:
        parent = dep.get("ref", "")
        for child in dep.get("dependsOn", []) or []:
            key = f"{parent}>>{child}"
            if key in seen:
                continue
            seen.add(key)
            edges.append({"from": parent, "to": child})

    return {"nodes": nodes, "edges": edges}


def annotate_cves(
    graph: dict[str, Any], cve_map: dict[str, list[str]]
) -> dict[str, Any]:
    """Attach known CVEs to graph nodes by package name (case/fuzzy match).

    cve_map: {package_name: [cve...]} from osv-scanner.
    """
    for node in graph.get("nodes", []):
        label = node.get("label", "")
        name = label.split("@")[0]
        node["cves"] = cve_map.get(name, [])
    # reachability: count of CVEs on the whole graph
    all_cves: list[str] = []
    for n in graph.get("nodes", []):
        all_cves.extend(n.get("cves", []))
    graph["cve_total"] = len(set(all_cves))
    return graph


def _dep_edges(edges: list[dict[str, str]]) -> list[tuple[str, str]]:
    """Normalise edges to a stable (from, to) list for traversal."""
    return [(e.get("from", ""), e.get("to", "")) for e in edges]


def reachability_from_roots(graph: dict[str, Any]) -> list[str]:
    """Return the set of node ids reachable from any root node.

    A "root" is a node that nothing depends on (nothing points to it) — normally
    the application/top-level package. Reachable = on an active dependency path
    from a root (directly or transitively). This is genuine graph reachability,
    not a claim about code-level call paths (which needs per-language call-graph
    analysis we don't fabricate).
    """
    nodes = graph.get("nodes", [])
    edges = _dep_edges(graph.get("edges", []))

    # Build parent->children adjacency and a reverse index (who points at me).
    children: dict[str, list[str]] = {}
    parents: dict[str, list[str]] = {}
    for frm, to in edges:
        children.setdefault(frm, []).append(to)
        parents.setdefault(to, []).append(frm)

    node_ids = {n.get("id", "") for n in nodes}
    # Roots = top of a dependency tree: nothing points to them AND they pull
    # something in (have children). Leaf orphans (no parent, no child) are not
    # part of any path and are correctly left unreachable.
    has_parent = set(parents.keys())
    top_level = node_ids - has_parent
    roots = {nid for nid in top_level if children.get(nid)}
    if not roots:
        # Flat/cyclic graph: fall back to everything with no parent.
        roots = top_level or node_ids

    if not roots:
        # Degenerate: every node is a child (cyclic or flat) — fall back to all.
        return sorted(node_ids)

    reachable: set[str] = set()
    stack = list(roots)
    while stack:
        cur = stack.pop()
        if cur in reachable:
            continue
        reachable.add(cur)
        for ch in children.get(cur, []):
            if ch in node_ids and ch not in reachable:
                stack.append(ch)
    return sorted(reachable)


def build_supply_chain_map(
    sbom_path: str | Path, cve_map: dict[str, list[str]]
) -> dict[str, Any]:
    """Build the full {graph, component CVE list, summary, reachability} map."""
    comps = parse_sbom(sbom_path)
    graph = build_graph(sbom_path)
    graph = annotate_cves(graph, cve_map)

    reachable = reachability_from_roots(graph)
    reachable_set = set(reachable)

    # Annotate each node with reachability + flag vulnerable-and-reachable
    # (the real "this CVEs is on an active dependency path" signal).
    for node in graph.get("nodes", []):
        node["reachable"] = node.get("id", "") in reachable_set
        node["reachable_cves"] = node["cves"] if node["reachable"] else []

    vuln_reachable = [
        n.get("label", "")
        for n in graph.get("nodes", [])
        if n.get("reachable") and n.get("cves")
    ]

    return {
        "components": comps,
        "graph": graph,
        "summary": {
            "components": len(comps),
            "edges": len(graph.get("edges", [])),
            "cves": graph.get("cve_total", 0),
            "reachable_nodes": len(reachable),
            "vulnerable_reachable": len(vuln_reachable),
        },
        "reachable": reachable,
        "vulnerable_reachable": vuln_reachable,
    }
